<script setup>
import {computed,ref,watch} from 'vue'
import {relationPresets,quantifiedFormulas,quantifierSteps} from '../services/predicate-models.mjs'
import SimulationControls from './SimulationControls.vue'
import PredicateCode from './PredicateCode.vue'
const id=ref('ae'),preset=ref('identity'),matrix=ref(relationPresets.identity.matrix.map(x=>x.slice())),step=ref(0),names=['An','Bình','Chi']
const trace=computed(()=>Array.from(quantifierSteps(matrix.value,id.value))),state=computed(()=>trace.value[Math.min(step.value,trace.value.length-1)]),key=computed(()=>JSON.stringify([id.value,matrix.value]))
watch(key,()=>step.value=0);watch(preset,()=>matrix.value=relationPresets[preset.value].matrix.map(x=>x.slice()))
const other=computed(()=>Object.keys(quantifiedFormulas).map(id=>({id,value:Array.from(quantifierSteps(matrix.value,id)).at(-1).value})))
const message=computed(()=>{const s=state.value,f=quantifiedFormulas[id.value];if(s.phase==='pair')return `Cố định x = ${names[s.x]}, y = ${names[s.y]}. R(x, y) ${s.value?'đúng':'sai'} trong quan hệ đã nhập.`;if(s.phase==='row')return `Với ${s.outerVariable} = ${names[s.index]}, ${f.inner==='some'?'có ít nhất một':'mọi'} ${s.outerVariable==='x'?'y':'x'} làm R(x, y) đúng: ${s.value?'Đúng':'Sai'}.`;if(s.phase==='result')return `Kết quả ${s.value?'Đúng':'Sai'} trong diễn giải hữu hạn này. ${s.witness!==null&&s.witness>=0?'Nhân chứng cho '+s.outerVariable+' là '+names[s.witness]+'.':s.counterexample!==null&&s.counterexample>=0?'Phản ví dụ cho '+s.outerVariable+' là '+names[s.counterexample]+'.':''} Đây chưa phải kiểm tra đúng trong mọi mô hình.`;return 'Hàng là x, cột là y. Bấm từng ô để đổi quan hệ. Lượng từ trong được tính trước khi tổng hợp theo lượng từ ngoài.'})
</script>
<template><section class="math-lab predicate-quantifier" aria-label="Mô phỏng lượng từ trên quan hệ hữu hạn"><div class="predicate-settings"><label>Diễn giải mẫu<select v-model="preset"><option v-for="(p,k) in relationPresets" :key="k" :value="k">{{ p.title }}</option></select></label><label>Câu được kiểm tra<select v-model="id"><option v-for="(f,k) in quantifiedFormulas" :key="k" :value="k">{{ f.text }}</option></select></label></div><p>{{ quantifiedFormulas[id].title }}.</p><SimulationControls v-model="step" :max="trace.length-1" :reset-key="key"/><div class="relation-grid" role="group" aria-label="Ma trận quan hệ R, hàng x và cột y"><span>x ↓ · y →</span><strong v-for="n in names" :key="n">{{ n }}</strong><template v-for="(row,x) in matrix" :key="x"><strong>{{ names[x] }}</strong><button v-for="(v,y) in row" :key="y" type="button" :aria-pressed="v" :aria-label="`Quan hệ từ ${names[x]} tới ${names[y]}, ${v?'Đúng':'Sai'}`" :class="{selected:state.x===x&&state.y===y,on:v}" @click="matrix[x][y]=!v">{{ v?'Đúng':'Sai' }}</button></template></div><p class="predicate-status" role="status">{{ message }}</p><div class="quantifier-results"><span v-for="r in other" :key="r.id">{{ quantifiedFormulas[r.id].text }}: {{ r.value?'Đúng':'Sai' }}</span></div><details><summary>Cách đọc và phép tổng hợp</summary><p>∀y∃x đọc từng cột, kiểm tra có ô Đúng rồi lấy hội kết quả các cột. ∃x∀y tìm một hàng toàn Đúng. Cùng một nhân chứng x không bắt buộc dùng cho các cột khác nhau trong ∀y∃x.</p><p>Ba đối tượng trong miền đều được liệt kê và quan hệ được khai báo đầy đủ. Việc không đánh dấu một ô được hiểu là Sai trong diễn giải này. Cơ sở tri thức chưa biết một sự thực là một tình huống khác.</p><p>Kết quả theo biến ngoài đã tính: {{ state.rows.map((v,i)=>names[i]+': '+(v?'Đúng':'Sai')).join(' · ')||'Chưa có' }}.</p></details><PredicateCode name="quantifierSteps" :phase="state.phase"/></section></template>
<style scoped>
.predicate-quantifier{min-width:0}.predicate-settings{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.predicate-quantifier label{display:grid;gap:6px;font:var(--fs-small)/1.6 var(--font-ui)}select{min-width:0;max-width:100%;min-height:44px;padding:8px;background:var(--paper);color:var(--ink);border:1px solid var(--control);border-radius:var(--radius);font:inherit}.relation-grid{display:grid;grid-template-columns:1.2fr repeat(3,1fr);gap:8px;align-items:center;margin:20px 0;font:var(--fs-small)/1.5 var(--font-ui)}.relation-grid strong{text-align:center}.relation-grid button{min-height:44px;padding:8px 2px;border:1px solid var(--control);border-radius:var(--radius);background:var(--paper);color:var(--ink);font:inherit;cursor:pointer}.relation-grid button.on{background:var(--xanh-soft);border-color:var(--xanh)}.relation-grid button.selected{outline:3px solid var(--tim);outline-offset:1px}.predicate-status{padding:12px;border-left:3px solid var(--tim);background:var(--tim-soft)}.quantifier-results{display:grid;gap:8px;font:var(--fs-small)/1.7 var(--font-ui)}.quantifier-results span{padding:8px;border:1px solid var(--rule);border-radius:var(--radius)}summary{min-height:44px;cursor:pointer}:is(button,select,summary):focus-visible{outline:3px solid var(--tim);outline-offset:3px}@media(max-width:480px){.predicate-settings{grid-template-columns:1fr}.relation-grid{gap:6px}}
</style>
